// Parallel World Portal - time dilation calculator (Mark 1 demonstration run) [real physics]
// Run with: node demo.js
'use strict';
function dilation(v){ return 1/Math.sqrt(1-v*v); } // v as fraction of c
console.log("Parallel World Portal - relativistic time dilation (verified physics)");
console.log("==================================================");
var speeds=[0.1,0.5,0.9,0.99];
for(var i=0;i<speeds.length;i++){
  var g=dilation(speeds[i]);
  console.log("at "+(speeds[i]*100)+"% light speed: 1 ship-year = "+g.toFixed(2)+" Earth-years");
}
console.log("Speculative generations extend this principle to engineered temporal translation.");

